
        /* ================= ENHANCED CINEMATIC AUDIO ENGINE ================= */
        let audioCtx = null;
        let sfxBus = null;
        let ambienceBus = null;
        let windOsc = null;
        let windGain = null;
        let isAmbiencePlaying = false;
        let isSFXEnabled = true;
        let isMusicEnabled = true;
        let musicStarted = false;
        let musicVolume = .36;
        let sfxVolume = .64;
        let ambienceVolume = .30;
        let currentMusicPhase = 'menu';
        let currentMusicTrack = null;
        let fadeTimer = null;
        const musicTracks = {};
        const embeddedMusic_day = 'data:audio/mpeg;base64,';
        const embeddedMusic_defeat = 'data:audio/mpeg;base64,';
        const embeddedMusic_menu = 'data:audio/mpeg;base64,';
        const embeddedMusic_night = 'data:audio/mpeg;base64,';
        const embeddedMusic_victory = 'data:audio/mpeg;base64,';
        const soundTrackNames = ['menu', 'night', 'day', 'victory', 'defeat'];
        const safePref = (key, fallback) => {try {const val = localStorage.getItem('wolves_v2_'+key);return val === null ? fallback : JSON.parse(val);}catch(e){return fallback;}};
        const storePref = (key,val) => {try {localStorage.setItem('wolves_v2_'+key,JSON.stringify(val));}catch(e){}};
        isMusicEnabled = safePref('music', true);
        isSFXEnabled = safePref('sfx', true);
        musicVolume = Math.max(0,Math.min(1,Number(safePref('musicVolume', .36))||0));
        sfxVolume = Math.max(0,Math.min(1,Number(safePref('sfxVolume', .64))||0));
        ambienceVolume = Math.max(0,Math.min(1,Number(safePref('windVolume', .30))||0));

        // Synthesized audio works when the game is opened directly from index.html, no web service needed.
        function getAudioContext() {
            try {
                if (!audioCtx) {
                    const Context = window.AudioContext || window.webkitAudioContext;
                    if (!Context) return null;
                    audioCtx = new Context();
                    sfxBus = audioCtx.createGain();
                    sfxBus.gain.value = sfxVolume;
                    sfxBus.connect(audioCtx.destination);
                    ambienceBus = audioCtx.createGain();
                    ambienceBus.gain.value = ambienceVolume;
                    ambienceBus.connect(audioCtx.destination);
                }
                if(audioCtx.state === 'suspended') audioCtx.resume().catch(()=>{});
                return audioCtx;
            } catch (e) {return null;}
        }
        function addTone(ctx,at,startFreq,endFreq,duration,level=0.1,wave='sine',attack=.014){
            const o=ctx.createOscillator(),g=ctx.createGain();
            o.type=wave;
            o.frequency.setValueAtTime(Math.max(30,startFreq),at);
            if(endFreq && endFreq!==startFreq)o.frequency.exponentialRampToValueAtTime(Math.max(30,endFreq),at+duration*.9);
            g.gain.setValueAtTime(.00001,at);
            g.gain.exponentialRampToValueAtTime(Math.max(.00002,level),at+Math.min(attack,duration*.4));
            g.gain.exponentialRampToValueAtTime(.00001,at+duration);
            o.connect(g);g.connect(sfxBus);
            o.start(at);o.stop(at+duration+.025);
        }
        function addNoise(ctx,at,duration,level=.07,frequency=550,filterType='lowpass'){
            const n=Math.max(200,Math.floor(ctx.sampleRate*duration));
            const b=ctx.createBuffer(1,n,ctx.sampleRate),d=b.getChannelData(0);
            for(let i=0;i<n;i++)d[i]=Math.random()*2-1;
            const src=ctx.createBufferSource(),f=ctx.createBiquadFilter(),g=ctx.createGain();
            src.buffer=b;f.type=filterType;f.frequency.value=frequency;
            g.gain.setValueAtTime(level,at);g.gain.exponentialRampToValueAtTime(.00001,at+duration);
            src.connect(f);f.connect(g);g.connect(sfxBus);src.start(at);src.stop(at+duration+.02);
        }
        function playSound(type){
            if(!isSFXEnabled)return;
            try {
                const ctx=getAudioContext();if(!ctx)return;
                const now=ctx.currentTime+.012;
                switch(type){
                    case 'click':addTone(ctx,now,580,350,.08,.10,'sine');break;
                    case 'select':addTone(ctx,now,540,730,.13,.15,'triangle');addTone(ctx,now+.05,780,940,.16,.09,'sine');break;
                    case 'chime':addTone(ctx,now,523,659,.47,.17,'triangle');addTone(ctx,now+.14,784,1046,.50,.10,'sine');break;
                    case 'reveal':addTone(ctx,now,392,587,.55,.13,'sine');addTone(ctx,now+.10,587,880,.55,.11,'triangle');addTone(ctx,now+.22,784,1175,.9,.09,'sine');break;
                    case 'howl':addTone(ctx,now,200,370,1.05,.21,'sawtooth',.22);addTone(ctx,now+.48,395,250,1.2,.15,'triangle',.18);addNoise(ctx,now+.2,.7,.05,480);break;
                    case 'gavel':addTone(ctx,now,170,45,.22,.21,'square');addNoise(ctx,now,.1,.14,1250);break;
                    case 'night':addTone(ctx,now,260,110,1.18,.16,'triangle',.22);addTone(ctx,now+.12,390,150,1.13,.14,'sine',.23);addNoise(ctx,now+.02,1.22,.05,700);break;
                    case 'dawn':addTone(ctx,now,392,587,.9,.1,'triangle',.15);addTone(ctx,now+.19,523,784,1.1,.12,'sine',.12);addTone(ctx,now+.35,659,988,1.3,.1,'triangle',.16);break;
                    case 'heal':addTone(ctx,now,440,660,.45,.12,'sine');addTone(ctx,now+.16,587,880,.48,.15,'triangle');addTone(ctx,now+.32,784,1175,.64,.08,'sine');break;
                    case 'inspect':addTone(ctx,now,784,1047,.3,.15,'sine');addTone(ctx,now+.13,1047,1568,.65,.07,'triangle');break;
                    case 'shot':addNoise(ctx,now,.2,.4,1500);addTone(ctx,now,105,42,.44,.24,'sawtooth');break;
                    case 'danger':addTone(ctx,now,270,180,.49,.14,'sawtooth');addTone(ctx,now+.15,180,80,.56,.18,'triangle');addNoise(ctx,now,.16,.12,400);break;
                    case 'vote':addTone(ctx,now,220,110,.23,.18,'triangle');addNoise(ctx,now,.12,.12,900);break;
                    case 'tick':addTone(ctx,now,820,660,.065,.075,'sine');break;
                    case 'victory':[523,659,784,1046].forEach((f,i)=>addTone(ctx,now+i*.14,f,f*1.01,1.1,.15,'triangle'));break;
                    case 'defeat':[392,330,262,196].forEach((f,i)=>addTone(ctx,now+i*.2,f,f*.75,1.0,.16,'sawtooth'));break;
                }
            }catch(e){console.warn('Nonfatal SFX error',e);}
        }
        function announceRoleCall(text){
            if(!isSFXEnabled || !('speechSynthesis' in window))return;
            try {window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.rate=.91;u.pitch=.87;u.volume=Math.min(1,sfxVolume+.13);window.speechSynthesis.speak(u);}catch(e){}
        }
        function initMusic(){
            if(musicStarted)return;
            musicStarted=true;
            soundTrackNames.forEach(name=>{
                const audio=new Audio(({menu:embeddedMusic_menu,night:embeddedMusic_night,day:embeddedMusic_day,victory:embeddedMusic_victory,defeat:embeddedMusic_defeat})[name]);
                audio.loop=true;audio.preload='auto';audio.volume=0;
                musicTracks[name]=audio;
            });
        }
        function startMusicFromGesture(){
            if(!isMusicEnabled)return;
            initMusic();
            const track=musicTracks[currentMusicPhase];
            if(!track)return;
            if(track!==currentMusicTrack){setMusicPhase(currentMusicPhase);return;}
            if(track.paused)track.play().catch(()=>{});
        }
        function setMusicPhase(phase){
            if(!soundTrackNames.includes(phase))phase='menu';
            currentMusicPhase=phase;
            if(!isMusicEnabled || !musicStarted)return;
            const upcoming=musicTracks[phase];
            if(currentMusicTrack===upcoming){if(upcoming.paused)upcoming.play().catch(()=>{});return;}
            if(fadeTimer){clearInterval(fadeTimer);fadeTimer=null;}
            const old=currentMusicTrack;
            currentMusicTrack=upcoming;
            upcoming.currentTime=0;
            upcoming.volume=0;
            upcoming.play().catch(()=>{});
            const started=performance.now(),fadeMs=1100;
            const oldVolume=old?old.volume:0;
            fadeTimer=setInterval(()=>{
                const amount=Math.min(1,(performance.now()-started)/fadeMs);
                if(old)old.volume=Math.min(1,Math.max(0,oldVolume*(1-amount)));
                upcoming.volume=Math.min(1,Math.max(0,musicVolume*amount));
                if(amount>=1){clearInterval(fadeTimer);fadeTimer=null;if(old){old.pause();old.currentTime=0;}}
            },45);
        }
        function updateMusicButton(){
            const i=document.getElementById('musicIcon'),l=document.getElementById('musicLabel');
            if(i)i.className=isMusicEnabled?'fas fa-music text-amber-400':'fas fa-music text-slate-500';
            if(l)l.textContent=isMusicEnabled?'Music On':'Music Off';
            const b=document.getElementById('musicBtn');if(b)b.setAttribute('aria-pressed',String(isMusicEnabled));
        }
        function toggleMusic(){
            isMusicEnabled=!isMusicEnabled;storePref('music',isMusicEnabled);updateMusicButton();
            if(isMusicEnabled){startMusicFromGesture();setMusicPhase(currentMusicPhase);}else{
                if(fadeTimer){clearInterval(fadeTimer);fadeTimer=null;}
                Object.values(musicTracks).forEach(track=>track.pause());
                currentMusicTrack=null;
            }
            playSound('click');
        }
        function toggleSFX(){
            isSFXEnabled=!isSFXEnabled;storePref('sfx',isSFXEnabled);
            const icon=document.getElementById('sfxIcon');
            if(icon)icon.className=isSFXEnabled?'fas fa-volume-high text-blue-400':'fas fa-volume-xmark text-slate-500';
            if(!isSFXEnabled && 'speechSynthesis' in window)window.speechSynthesis.cancel();
            const btn=document.getElementById('sfxBtn');if(btn)btn.setAttribute('aria-pressed',String(isSFXEnabled));
        }
        function updateAmbienceButton(){
            const icon=document.getElementById('ambienceIcon'),label=document.getElementById('ambienceLabel');
            if(icon)icon.className=isAmbiencePlaying?'fas fa-wind text-blue-400':'fas fa-wind text-slate-400';
            if(label)label.textContent=isAmbiencePlaying?'Wind On':'Wind Off';
            const btn=document.getElementById('ambienceBtn');if(btn)btn.setAttribute('aria-pressed',String(isAmbiencePlaying));
        }
        function toggleAmbience(){
            const ctx=getAudioContext();if(!ctx)return;
            if(isAmbiencePlaying){
                const source=windOsc,gn=windGain;
                isAmbiencePlaying=false;windOsc=null;windGain=null;
                if(gn)gn.gain.setTargetAtTime(.00001,ctx.currentTime,.22);
                if(source){setTimeout(()=>{try{source.stop()}catch(e){}},900);}
            }else{
                const n=ctx.sampleRate*2;
                const buffer=ctx.createBuffer(1,n,ctx.sampleRate),data=buffer.getChannelData(0);
                for(let i=0;i<n;i++)data[i]=Math.random()*2-1;
                const noise=ctx.createBufferSource(),filter=ctx.createBiquadFilter(),gain=ctx.createGain();
                noise.buffer=buffer;noise.loop=true;filter.type='lowpass';filter.frequency.value=180;
                gain.gain.setValueAtTime(.00001,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.105,ctx.currentTime+1.8);
                noise.connect(filter);filter.connect(gain);gain.connect(ambienceBus);noise.start();
                windOsc=noise;windGain=gain;isAmbiencePlaying=true;
            }
            updateAmbienceButton();playSound('click');
        }
        function setVolume(kind,raw){
            const val=Math.max(0,Math.min(1,Number(raw)/100));
            const output=document.getElementById(kind+'VolumeLabel');if(output)output.textContent=Math.round(val*100)+'%';
            if(kind==='music'){musicVolume=val;storePref('musicVolume',val);if(currentMusicTrack && !fadeTimer)currentMusicTrack.volume=val;}
            if(kind==='sfx'){sfxVolume=val;storePref('sfxVolume',val);if(sfxBus)sfxBus.gain.value=val;}
            if(kind==='wind'){ambienceVolume=val;storePref('windVolume',val);if(ambienceBus)ambienceBus.gain.value=val;}
        }
        function initializeAudioControls(){
            updateMusicButton();updateAmbienceButton();
            const sx=document.getElementById('sfxIcon');if(sx)sx.className=isSFXEnabled?'fas fa-volume-high text-blue-400':'fas fa-volume-xmark text-slate-500';
            [['music',musicVolume],['sfx',sfxVolume],['wind',ambienceVolume]].forEach(([key,value])=>{
                const input=document.getElementById(key+'Volume');if(input)input.value=Math.round(value*100);
                const output=document.getElementById(key+'VolumeLabel');if(output)output.textContent=Math.round(value*100)+'%';
            });
            document.getElementById('reduceMotionToggle').checked=!!safePref('reduceMotion',false);
            setMotionPreference(document.getElementById('reduceMotionToggle').checked);
            document.addEventListener('pointerdown',e=>{
                if(e.target.closest('#musicBtn'))return;
                if(isMusicEnabled)startMusicFromGesture();
            },{passive:true});
            document.addEventListener('keydown',e=>{
                if((e.key==='Enter'||e.key===' ') && isMusicEnabled)startMusicFromGesture();
            });
        }

        /* ================= SCENE TRANSITIONS & VISUAL FEEDBACK ================= */
        let transitionTimeout=null;
        const reduceMotionMedia=window.matchMedia?window.matchMedia('(prefers-reduced-motion: reduce)'):null;
        function motionAllowed(){return !document.body.classList.contains('motion-off') && !(reduceMotionMedia && reduceMotionMedia.matches);}
        function setMotionPreference(enabled){
            document.body.classList.toggle('motion-off', !!enabled);
            storePref('reduceMotion', !!enabled);
        }
        function cueCinematic(kicker,headline,theme='night-scene',symbol='fa-moon'){
            if(!motionAllowed())return;
            const el=document.getElementById('phaseCinematic');if(!el)return;
            clearTimeout(transitionTimeout);
            el.className='phase-cinematic '+theme;
            document.getElementById('cinematicKicker').textContent=kicker;
            document.getElementById('cinematicHeadline').textContent=headline;
            document.getElementById('cinematicSymbol').className='fas '+symbol+' text-3xl';
            void el.offsetWidth;
            el.classList.add('active');
            transitionTimeout=setTimeout(()=>el.classList.remove('active'),2000);
        }
        function flashFX(color='blue'){
            if(!motionAllowed())return;
            const el=document.getElementById('fxVignette');if(!el)return;
            el.className='fx-vignette '+color;
            void el.offsetWidth;
            el.classList.add('burst');
        }
        function animateCardFlip(revealed){
            const card=document.getElementById('roleCardHolder');if(!card)return;
            card.classList.toggle('role-revealed',!!revealed);
            if(motionAllowed()){
                card.classList.remove('role-flip');void card.offsetWidth;card.classList.add('role-flip');
            }
        }
        function animateTargetSelection(gridId){
            const grid=document.getElementById(gridId);if(!grid || !motionAllowed())return;
            const card=[...grid.children].find(c=>/border-(blue|amber|red)-[345]00/.test(c.className) || /bg-blue-500\/20/.test(c.className));
            if(card){card.classList.remove('fx-selected');void card.offsetWidth;card.classList.add('fx-selected');}
        }
        function sparkVictory(isWolf){
            const host=document.getElementById('victoryConfetti');if(!host)return;
            host.replaceChildren();if(!motionAllowed())return;
            const colors=isWolf?['#ef4444','#f97316','#fb7185','#d19b43']:['#fbbf24','#fef3c7','#60a5fa','#fcd34d'];
            const count=Math.min(44,window.innerWidth<600?23:44);
            for(let i=0;i<count;i++){
                const spark=document.createElement('span');spark.className='confetti-spark';
                spark.style.left=(Math.random()*100)+'%';spark.style.backgroundColor=colors[i%colors.length];
                spark.style.setProperty('--fall-time',(2.6+Math.random()*2.5)+'s');
                spark.style.setProperty('--fall-delay',(Math.random()*1.6)+'s');
                spark.style.setProperty('--sway',((Math.random()-.5)*220)+'px');
                spark.style.setProperty('--spin',((Math.random()-.5)*1200)+'deg');
                host.appendChild(spark);
            }
            setTimeout(()=>host.replaceChildren(),7000);
        }
        function bindAnimationFeedback(){
            document.addEventListener('click',event=>{
                const button=event.target.closest('.wolf-btn');
                if(button && motionAllowed()){
                    button.classList.remove('tap-burst');void button.offsetWidth;button.classList.add('tap-burst');
                }
            });
            const timer=document.getElementById('timerDisplay');
            if(timer)timer.setAttribute('aria-live','off');
        }

        /* ================= GAME STATE MANAGEMENT & ROLES ================= */
        const ROLES = {
            WOLF: { title: 'Wolf', icon: 'fa-paw', color: 'text-red-400', desc: 'Eliminate non-wolves at night and avoid detection.' },
            SEER: { title: 'Seer', icon: 'fa-eye', color: 'text-blue-400', desc: 'Inspect players each night to discover their alignment.' },
            HEALER: { title: 'Healer', icon: 'fa-heart', color: 'text-emerald-400', desc: 'Protect players at night based on doctor limits.' },
            HUNTER: { title: 'Hunter', icon: 'fa-crosshairs', color: 'text-amber-400', desc: 'If eliminated, immediately take down a target.' },
            VILLAGER: { title: 'Villager', icon: 'fa-user', color: 'text-slate-300', desc: 'Deduce who the wolves are and vote them out during day debate.' }
        };

        let roleCounts = {
            wolves: 2,
            healers: 1,
            seers: 1,
            hunters: 1
        };

        let doctorRule = 'unlimited'; // 'unlimited', 'no_consecutive', 'no_self', 'max_1', 'max_2'
        let healerSaveDisclosure = 'reveal'; // 'reveal' shows the protected player's name; 'secret' hides it from the morning announcement
        let seerRule = 'unlimited';   // 'unlimited', 'max_1', 'max_2', 'max_3'
        let hunterRule = 'max_1';     // 'max_1', 'max_2', 'max_3', 'unlimited'

        let gameState = {
            mode: 'solo', // 'solo' or 'pass'
            playerCount: 7,
            players: [], // Array of { id, name, role, isAlive, isAI, successfulHeals, lastProtectedId, seerInspectionsCount, hunterShotsFired }
            currentDay: 1,
            phase: 'setup',
            revealIndex: 0,

            // Night step tracking
            nightStep: 'wolves',
            nightTargets: {
                wolfKill: null,
                healerProtect: null,
                seerInspect: null,
                hunterTarget: null
            },

            // Hunter death trigger queue
            pendingHunterShot: null,
            selectedHunterShotId: null,

            // Discussion & Voting
            discussionTimer: null,
            timerSeconds: 120,
            selectedVoteId: null,
            selectedNightTarget: null,
            nightEvents: [],
            votes: {},
            lastEliminatedPlayer: null
        };


        /* ================= SETUP CONTROLS & REAL-TIME VALIDATION ================= */
        function updatePlayerCount(val) {
            gameState.playerCount = parseInt(val);
            document.getElementById('playerCountLabel').textContent = `${val} Players`;
            validateAndCalculateRoles();
            renderPlayerInputs();
        }

        function adjustRoleCount(roleType, delta) {
            playSound('click');
            const newCount = roleCounts[roleType] + delta;

            let minLimit = 0;
            let maxLimit = 2;
            if (roleType === 'wolves') { minLimit = 1; maxLimit = 4; }

            if (newCount >= minLimit && newCount <= maxLimit) {
                roleCounts[roleType] = newCount;
                document.getElementById(`${roleType}CountText`).textContent = newCount;
                validateAndCalculateRoles();
            }
        }

        function resetDefaultRoles() {
            playSound('click');
            const count = gameState.playerCount;
            roleCounts.wolves = count >= 10 ? 3 : (count >= 6 ? 2 : 1);
            roleCounts.healers = count >= 6 ? 1 : 0;
            roleCounts.seers = 1;
            roleCounts.hunters = count >= 8 ? 1 : 0;

            document.getElementById('wolvesCountText').textContent = roleCounts.wolves;
            document.getElementById('healersCountText').textContent = roleCounts.healers;
            document.getElementById('seersCountText').textContent = roleCounts.seers;
            document.getElementById('huntersCountText').textContent = roleCounts.hunters;

            validateAndCalculateRoles();
        }

        function updateDoctorRuleSetting(val) {
            doctorRule = val;
        }

        function updateHealerSaveDisclosure(val) {
            healerSaveDisclosure = val === 'secret' ? 'secret' : 'reveal';
        }

        function updateSeerRuleSetting(val) {
            seerRule = val;
        }

        function updateHunterRuleSetting(val) {
            hunterRule = val;
        }

        function validateAndCalculateRoles() {
            const totalSpecial = roleCounts.wolves + roleCounts.healers + roleCounts.seers + roleCounts.hunters;
            const remainingVillagers = gameState.playerCount - totalSpecial;

            const villagerText = document.getElementById('villagersCountText');
            const warningBox = document.getElementById('balanceWarningBox');
            const warningIcon = document.getElementById('balanceIcon');
            const warningText = document.getElementById('balanceText');
            const startBtn = document.getElementById('startGameBtn');

            if (remainingVillagers < 0) {
                villagerText.textContent = "Invalid (Too many roles)";
                villagerText.className = "font-bold text-red-400";

                warningBox.className = "p-3 rounded-xl border bg-red-950/40 border-red-500/50 text-red-300 text-xs font-semibold flex items-center space-x-2";
                warningIcon.className = "fas fa-triangle-exclamation text-red-400";
                warningText.textContent = `Total special roles (${totalSpecial}) exceed total players (${gameState.playerCount})!`;
                startBtn.disabled = true;
                return;
            }

            villagerText.textContent = `${remainingVillagers} Villagers`;
            villagerText.className = "font-bold text-amber-400";

            // Check Wolf ratio balance
            const nonWolves = gameState.playerCount - roleCounts.wolves;
            if (roleCounts.wolves >= nonWolves) {
                warningBox.className = "p-3 rounded-xl border bg-amber-950/40 border-amber-500/50 text-amber-300 text-xs font-semibold flex items-center space-x-2";
                warningIcon.className = "fas fa-triangle-exclamation text-amber-400";
                warningText.textContent = `Warning: Wolves (${roleCounts.wolves}) meet or exceed Villagers (${nonWolves}). Wolves win instantly!`;
                startBtn.disabled = true;
            } else {
                warningBox.className = "p-3 rounded-xl border bg-emerald-950/40 border-emerald-500/50 text-emerald-300 text-xs font-semibold flex items-center space-x-2";
                warningIcon.className = "fas fa-check-circle text-emerald-400";
                warningText.textContent = `Setup valid! ${roleCounts.wolves} Wolves vs ${nonWolves} Town members.`;
                startBtn.disabled = false;
            }
        }

        function setGameMode(mode) {
            playSound('click');
            gameState.mode = mode;

            document.getElementById('modeBtnSolo').className = mode === 'solo'
                ? "wolf-btn p-4 text-left flex flex-col justify-between border-blue-400 bg-blue-500/10"
                : "wolf-btn p-4 text-left flex flex-col justify-between";

            document.getElementById('modeBtnPass').className = mode === 'pass'
                ? "wolf-btn p-4 text-left flex flex-col justify-between border-amber-400 bg-amber-500/10"
                : "wolf-btn p-4 text-left flex flex-col justify-between";

            renderPlayerInputs();
        }

        function renderPlayerInputs() {
            const container = document.getElementById('playerNamesContainer');
            container.innerHTML = '';

            if (gameState.mode === 'solo') {
                container.innerHTML = `
                    <label class="block text-[11px] font-bold text-slate-400 uppercase tracking-wider">Your Name</label>
                    <input type="text" id="humanPlayerName" value="You" class="w-full bg-slate-900 border border-slate-700 rounded-xl px-3 py-2 text-xs text-white focus:outline-none focus:border-blue-400">
                `;
            } else {
                let html = `<label class="block text-[11px] font-bold text-slate-400 uppercase tracking-wider">Player Names</label><div class="grid grid-cols-2 gap-2">`;
                for (let i = 1; i <= gameState.playerCount; i++) {
                    html += `<input type="text" id="pNameInput_${i}" value="Player ${i}" class="bg-slate-900 border border-slate-700 rounded-xl px-3 py-1.5 text-xs text-white focus:outline-none focus:border-amber-400">`;
                }
                html += `</div>`;
                container.innerHTML = html;
            }
        }

        /* ================= GAME START & ROLE DISTRIBUTION ================= */
        function startGame() {
            playSound('howl');

            gameState.players = [];
            const count = gameState.playerCount;

            const remainingVillagers = count - (roleCounts.wolves + roleCounts.healers + roleCounts.seers + roleCounts.hunters);

            let rolePool = [];
            for (let i = 0; i < roleCounts.wolves; i++) rolePool.push('WOLF');
            for (let i = 0; i < roleCounts.seers; i++) rolePool.push('SEER');
            for (let i = 0; i < roleCounts.healers; i++) rolePool.push('HEALER');
            for (let i = 0; i < roleCounts.hunters; i++) rolePool.push('HUNTER');
            for (let i = 0; i < remainingVillagers; i++) rolePool.push('VILLAGER');

            // Fisher-Yates shuffle gives a fairer role distribution than sort(Math.random).
            for (let i = rolePool.length - 1; i > 0; i--) {
                const j = Math.floor(Math.random() * (i + 1));
                [rolePool[i], rolePool[j]] = [rolePool[j], rolePool[i]];
            }

            const botNames = ['Luna', 'Fenrir', 'Soren', 'Astrid', 'Kael', 'Freya', 'Bjorn', 'Eira', 'Torin', 'Vane', 'Sigrid', 'Rowan', 'Gunnar', 'Saga', 'Ivar', 'Valda'];

            for (let i = 0; i < count; i++) {
                let pName = '';
                let isAI = false;

                if (gameState.mode === 'solo') {
                    if (i === 0) {
                        pName = document.getElementById('humanPlayerName')?.value.trim() || 'You';
                        isAI = false;
                    } else {
                        pName = botNames[i - 1] || `Bot ${i}`;
                        isAI = true;
                    }
                } else {
                    pName = document.getElementById(`pNameInput_${i + 1}`)?.value.trim() || `Player ${i + 1}`;
                    isAI = false;
                }

                gameState.players.push({
                    id: i + 1,
                    name: pName,
                    role: rolePool[i],
                    isAlive: true,
                    isAI: isAI,
                    successfulHeals: 0,
                    lastProtectedId: null,
                    seerInspectionsCount: 0,
                    hunterShotsFired: 0
                });
            }

            gameState.currentDay = 1;

            if (gameState.mode === 'pass') {
                cueCinematic('THE PACK ASSEMBLES', 'YOUR FATE AWAITS','night-scene','fa-paw');
                gameState.revealIndex = 0;
                switchView('viewRoleReveal');
                setupRoleRevealCard();
            } else {
                startNightPhase();
            }
        }


        /* ================= SECRET ROLE REVEAL ================= */
        function setupRoleRevealCard() {
            const player = gameState.players[gameState.revealIndex];
            if (!player) { startNightPhase(); return; }
            document.getElementById('revealPlayerName').textContent = player.name;

            document.getElementById('roleCardBack').classList.remove('hidden');
            document.getElementById('roleCardFront').classList.add('hidden');
            document.getElementById('roleCardHolder').classList.remove('role-revealed','role-flip');
            updateRoleRevealButton(false);

            const roleObj = ROLES[player.role];
            document.getElementById('roleTitle').textContent = roleObj.title;
            document.getElementById('roleTitle').className = `font-serif text-2xl font-bold uppercase tracking-wider ${roleObj.color}`;
            document.getElementById('roleIcon').className = `fas ${roleObj.icon} text-5xl ${roleObj.color}`;
            document.getElementById('roleDesc').textContent = roleObj.desc;

            const wolfTeamEl = document.getElementById('wolfTeammates');
            if (player.role === 'WOLF') {
                const otherWolves = gameState.players
                    .filter(p => p.role === 'WOLF' && p.id !== player.id)
                    .map(p => p.name);

                if (otherWolves.length > 0) {
                    wolfTeamEl.textContent = `Teammate Wolves: ${otherWolves.join(', ')}`;
                    wolfTeamEl.classList.remove('hidden');
                } else {
                    wolfTeamEl.classList.add('hidden');
                }
            } else {
                wolfTeamEl.classList.add('hidden');
            }
        }

        function updateRoleRevealButton(isRevealed) {
            const button = document.getElementById('revealRoleBtn');
            if (!button) return;
            button.innerHTML = isRevealed
                ? '<i class="fas fa-eye-slash mr-2"></i> Tap to Hide Role'
                : '<i class="fas fa-eye mr-2"></i> Tap to Reveal Role';
        }

        function showSecretRole() {
            const back = document.getElementById('roleCardBack');
            const front = document.getElementById('roleCardFront');
            if (!back || !front || !front.classList.contains('hidden')) return;
            playSound('reveal');
            animateCardFlip(true);
            back.classList.add('hidden');
            front.classList.remove('hidden');
            updateRoleRevealButton(true);
        }

        function hideSecretRole() {
            const back = document.getElementById('roleCardBack');
            const front = document.getElementById('roleCardFront');
            if (!back || !front) return;
            back.classList.remove('hidden');
            front.classList.add('hidden');
            animateCardFlip(false);
            updateRoleRevealButton(false);
        }

        function toggleSecretRole() {
            const front = document.getElementById('roleCardFront');
            if (!front) return;
            if (front.classList.contains('hidden')) showSecretRole();
            else hideSecretRole();
        }

        function nextPlayerRole() {
            playSound('click');
            gameState.revealIndex++;
            if (gameState.revealIndex < gameState.players.length) {
                setupRoleRevealCard();
            } else {
                startNightPhase();
            }
        }


        /* ================= NIGHT PHASE WORKFLOW & DOCTOR HEAL LIMIT ENFORCEMENT ================= */
        function startNightPhase() {
            gameState.phase = 'night';
            document.body.classList.remove('day-phase');
            setMusicPhase('night');
            playSound('night');
            cueCinematic('NIGHT '+gameState.currentDay, 'THE WOLVES AWAKEN','night-scene','fa-moon');

            gameState.nightTargets = { wolfKill: null, healerProtect: null, seerInspect: null, hunterTarget: null };
            gameState.selectedNightTarget = null;
            gameState.nightEvents = [];

            gameState.nightStep = 'wolves';

            // Show the night screen before rebuilding its controls. This prevents
            // stale hidden/layout state from the previous night carrying forward.
            switchView('viewNight');
            const nightBox = document.getElementById('nightInteractiveBox');
            const nightGrid = document.getElementById('nightPlayerGrid');
            const confirmButton = document.getElementById('confirmNightActionBtn');
            const finishSeerButton = document.getElementById('hideSeerTurnBtn');
            if (nightBox) nightBox.classList.remove('hidden');
            if (nightGrid) {
                nightGrid.classList.remove('hidden');
                nightGrid.innerHTML = '';
            }
            if (confirmButton) confirmButton.classList.remove('hidden');
            if (finishSeerButton) finishSeerButton.classList.add('hidden');
            closeModal('seerModal');
            const privacyShield = document.getElementById('seerPrivacyShield');
            privacyShield.classList.add('hidden');
            privacyShield.classList.remove('flex');
            // Day voting temporarily reuses the privacy button. Always restore its
            // night-turn handler before Night 2+ begins.
            const revealButton = document.getElementById('revealNightRoleBtn');
            if (revealButton) revealButton.onclick = revealNightRoleScreen;

            setupNightStepUI();
        }

        function setupNightStepUI() {
            gameState.selectedNightTarget = null;
            const titleEl = document.getElementById('nightStepTitle');
            const badgeEl = document.getElementById('nightStepBadge');
            const descEl = document.getElementById('nightInstructions');
            const iconEl = document.getElementById('nightPhaseIcon');
            const noticeEl = document.getElementById('nightRuleNotice');
            const privacyShield = document.getElementById('seerPrivacyShield');
            const interactiveBox = document.getElementById('nightInteractiveBox');
            const hideSeerBtn = document.getElementById('hideSeerTurnBtn');
            const confirmBtn = document.getElementById('confirmNightActionBtn');
            const headerCard = document.getElementById('nightHeaderCard');
            const iconHolder = document.getElementById('nightIconHolder');

            const activeRoleName = document.getElementById('activeRoleName');
            const activeRolePing = document.getElementById('activeRolePing');
            const activeRoleDot = document.getElementById('activeRoleDot');
            const turnIndicator = document.getElementById('roleTurnIndicator');

            gameState.selectedNightTarget = null;

            // Hard-reset every night action control on EVERY role turn and every new night.
            // Earlier turns (especially Seer in Pass & Play) can leave the action panel
            // hidden, which made the target choices appear to vanish on Night 2+.
            const nightGrid = document.getElementById('nightPlayerGrid');
            const revealButton = document.getElementById('revealNightRoleBtn');
            if (revealButton) revealButton.onclick = revealNightRoleScreen;
            interactiveBox.classList.remove('hidden');
            interactiveBox.style.display = '';
            if (nightGrid) {
                nightGrid.classList.remove('hidden');
                nightGrid.style.display = '';
                nightGrid.replaceChildren();
            }
            privacyShield.classList.add('hidden');
            privacyShield.classList.remove('flex');
            noticeEl.classList.add('hidden');
            hideSeerBtn.classList.add('hidden');
            confirmBtn.classList.remove('hidden');
            confirmBtn.disabled = false;

            // Reset highlight classes on header card
            headerCard.classList.remove('turn-highlight-wolves', 'turn-highlight-healer', 'turn-highlight-seer', 'turn-highlight-hunter');

            if (gameState.nightStep === 'wolves') {
                privacyShield.classList.add('hidden');
                interactiveBox.classList.remove('hidden');

                headerCard.classList.add('turn-highlight-wolves');
                iconHolder.className = "w-12 h-12 rounded-2xl bg-red-500/20 border border-red-400/40 flex items-center justify-center text-red-400 text-2xl shadow-inner";
                badgeEl.textContent = `Night ${gameState.currentDay} • Wolves Turn`;
                badgeEl.className = "text-[10px] font-extrabold uppercase tracking-widest text-red-400 bg-red-500/10 px-2.5 py-1 rounded-full border border-red-400/20";
                titleEl.textContent = "The Wolves Hunt";
                descEl.textContent = "Wolves wake up. Agree on one non-wolf target to eliminate from the pack.";
                iconEl.className = "fas fa-paw text-red-400";

                turnIndicator.className = "p-3.5 rounded-2xl border border-red-500/40 bg-red-950/30 flex items-center justify-between font-bold text-xs uppercase tracking-wider shadow-xl";
                activeRoleName.textContent = "WOLVES";
                activeRoleName.className = "text-red-400 font-extrabold ml-1";
                activeRolePing.className = "animate-ping absolute inline-flex h-full w-full rounded-full bg-red-400 opacity-75";
                activeRoleDot.className = "relative inline-flex rounded-full h-3 w-3 bg-red-500";

                noticeEl.textContent = "Wolves cannot attack other Wolves or themselves.";
                noticeEl.classList.remove('hidden');

                announceRoleCall("Wolves, open your eyes and choose a target.");
            } else if (gameState.nightStep === 'healer') {
                privacyShield.classList.add('hidden');
                interactiveBox.classList.remove('hidden');

                headerCard.classList.add('turn-highlight-healer');
                iconHolder.className = "w-12 h-12 rounded-2xl bg-emerald-500/20 border border-emerald-400/40 flex items-center justify-center text-emerald-400 text-2xl shadow-inner";
                badgeEl.textContent = `Night ${gameState.currentDay} • Healer Turn`;
                badgeEl.className = "text-[10px] font-extrabold uppercase tracking-widest text-emerald-400 bg-emerald-500/10 px-2.5 py-1 rounded-full border border-emerald-400/20";
                titleEl.textContent = "The Healer Awakens";
                descEl.textContent = "Healer wakes up. Protect a player according to custom doctor rules.";
                iconEl.className = "fas fa-heart text-emerald-400";

                turnIndicator.className = "p-3.5 rounded-2xl border border-emerald-500/40 bg-emerald-950/30 flex items-center justify-between font-bold text-xs uppercase tracking-wider shadow-xl";
                activeRoleName.textContent = "HEALER";
                activeRoleName.className = "text-emerald-400 font-extrabold ml-1";
                activeRolePing.className = "animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75";
                activeRoleDot.className = "relative inline-flex rounded-full h-3 w-3 bg-emerald-500";

                let ruleDesc = "";
                if (doctorRule === 'no_consecutive') ruleDesc = "Rule: Cannot protect same target twice in a row.";
                if (doctorRule === 'no_self') ruleDesc = "Rule: Cannot protect self.";
                if (doctorRule === 'max_1') ruleDesc = "Rule: Max 1 successful heal per game.";
                if (doctorRule === 'max_2') ruleDesc = "Rule: Max 2 successful heals per game.";

                if (ruleDesc) {
                    noticeEl.textContent = ruleDesc;
                    noticeEl.classList.remove('hidden');
                }

                announceRoleCall("Healer, open your eyes and select who to save.");
            } else if (gameState.nightStep === 'seer') {
                headerCard.classList.add('turn-highlight-seer');
                iconHolder.className = "w-12 h-12 rounded-2xl bg-blue-500/20 border border-blue-400/40 flex items-center justify-center text-blue-400 text-2xl shadow-inner";
                badgeEl.textContent = `Night ${gameState.currentDay} • Seer Turn`;
                badgeEl.className = "text-[10px] font-extrabold uppercase tracking-widest text-blue-400 bg-blue-500/10 px-2.5 py-1 rounded-full border border-blue-400/20";
                titleEl.textContent = "The Seer Inspects";
                descEl.textContent = "Seer wakes up. Choose one player to inspect their true alignment.";
                iconEl.className = "fas fa-eye text-blue-400";

                turnIndicator.className = "p-3.5 rounded-2xl border border-blue-500/40 bg-blue-950/30 flex items-center justify-between font-bold text-xs uppercase tracking-wider shadow-xl";
                activeRoleName.textContent = "SEER";
                activeRoleName.className = "text-blue-400 font-extrabold ml-1";
                activeRolePing.className = "animate-ping absolute inline-flex h-full w-full rounded-full bg-blue-400 opacity-75";
                activeRoleDot.className = "relative inline-flex rounded-full h-3 w-3 bg-blue-500";

                const activeSeer = gameState.players.find(p => p.role === 'SEER' && p.isAlive);
                let seerRuleDesc = "";
                if (seerRule !== 'unlimited' && activeSeer) {
                    const maxCount = parseInt(seerRule.split('_')[1]);
                    seerRuleDesc = `Limit: ${activeSeer.seerInspectionsCount}/${maxCount} Inspections Used.`;
                }
                if (seerRuleDesc) {
                    noticeEl.textContent = seerRuleDesc;
                    noticeEl.classList.remove('hidden');
                }

                announceRoleCall("Seer, open your eyes and choose a player to inspect.");

                const seerPlayer = gameState.players.find(p => p.role === 'SEER' && p.isAlive);

                if (gameState.mode === 'pass' && seerPlayer) {
                    document.getElementById('seerPrivacyName').textContent = `Pass Device To ${seerPlayer.name}`;
                    privacyShield.classList.remove('hidden');
                    interactiveBox.classList.add('hidden');
                } else if (gameState.mode === 'solo') {
                    privacyShield.classList.add('hidden');
                    interactiveBox.classList.remove('hidden');
                }
            } else if (gameState.nightStep === 'hunter') {
                headerCard.classList.add('turn-highlight-hunter');
                iconHolder.className = "w-12 h-12 rounded-2xl bg-amber-500/20 border border-amber-400/40 flex items-center justify-center text-amber-400 text-2xl shadow-inner";
                badgeEl.textContent = `Night ${gameState.currentDay} • Hunter Turn`;
                badgeEl.className = "text-[10px] font-extrabold uppercase tracking-widest text-amber-400 bg-amber-500/10 px-2.5 py-1 rounded-full border border-amber-400/20";
                titleEl.textContent = "The Hunter Tracks";
                descEl.textContent = "Hunter wakes up. Choose a target: if they are a Wolf, your silver shot will eliminate them!";
                iconEl.className = "fas fa-crosshairs text-amber-400";

                turnIndicator.className = "p-3.5 rounded-2xl border border-amber-500/40 bg-amber-950/30 flex items-center justify-between font-bold text-xs uppercase tracking-wider shadow-xl";
                activeRoleName.textContent = "HUNTER";
                activeRoleName.className = "text-amber-400 font-extrabold ml-1";
                activeRolePing.className = "animate-ping absolute inline-flex h-full w-full rounded-full bg-amber-400 opacity-75";
                activeRoleDot.className = "relative inline-flex rounded-full h-3 w-3 bg-amber-500";

                const activeHunter = gameState.players.find(p => p.role === 'HUNTER' && p.isAlive);
                let hunterRuleDesc = "";
                if (hunterRule !== 'unlimited' && activeHunter) {
                    const maxShots = parseInt(hunterRule.split('_')[1]);
                    hunterRuleDesc = `Limit: ${activeHunter.hunterShotsFired}/${maxShots} Shots Fired.`;
                }
                if (hunterRuleDesc) {
                    noticeEl.textContent = hunterRuleDesc;
                    noticeEl.classList.remove('hidden');
                }

                announceRoleCall("Hunter, open your eyes and mark your target.");

                const hunterPlayer = gameState.players.find(p => p.role === 'HUNTER' && p.isAlive);

                if (gameState.mode === 'pass' && hunterPlayer) {
                    document.getElementById('seerPrivacyName').textContent = `Pass Device To Hunter (${hunterPlayer.name})`;
                    privacyShield.classList.remove('hidden');
                    interactiveBox.classList.add('hidden');
                } else {
                    privacyShield.classList.add('hidden');
                    interactiveBox.classList.remove('hidden');
                }
            }

            // In pass-and-play mode, cover the entire screen for EVERY role turn.
            // This prevents the next player from seeing the previous role's action/results.
            if (gameState.mode === 'pass') {
                const roleDetails = {
                    wolves: { title: 'Pass Device To The Wolves', instructions: 'Only the Wolves should look at the screen. When everyone else has looked away, reveal the night action.', button: 'We Are The Wolves — Reveal Turn', icon: 'fa-paw' },
                    healer: { title: 'Pass Device To The Healer', instructions: 'Privately hand the device to the Healer. Make sure other players cannot see the screen before revealing the turn.', button: 'I Am The Healer — Reveal Turn', icon: 'fa-heart' },
                    seer: { title: 'Pass Device To The Seer', instructions: 'Privately hand the device to the Seer. Keep the inspection result hidden from everyone else.', button: 'I Am The Seer — Reveal Turn', icon: 'fa-eye' },
                    hunter: { title: 'Pass Device To The Hunter', instructions: 'Privately hand the device to the Hunter. Make sure other players cannot see the screen before revealing the turn.', button: 'I Am The Hunter — Reveal Turn', icon: 'fa-crosshairs' }
                };
                const privacy = roleDetails[gameState.nightStep];
                if (privacy) {
                    document.getElementById('seerPrivacyName').textContent = privacy.title;
                    document.getElementById('privacyShieldInstructions').textContent = privacy.instructions;
                    document.getElementById('revealNightRoleBtn').innerHTML = `<i class="fas ${privacy.icon} mr-2"></i> ${privacy.button}`;
                    privacyShield.classList.remove('hidden');
                    privacyShield.classList.add('flex');
                    interactiveBox.classList.add('hidden');
                }
            } else {
                privacyShield.classList.add('hidden');
                privacyShield.classList.remove('flex');
                interactiveBox.classList.remove('hidden');
            }

            // Always rebuild and show the target choices when a night role changes.
            // The old call to handleSoloAIMightStep() referenced a function that was
            // never defined, causing a JavaScript error on every solo-mode night turn.
            renderNightPlayerGrid();
        }

        function renderNightPlayerGrid() {
            const grid = document.getElementById('nightPlayerGrid');
            const interactiveBox = document.getElementById('nightInteractiveBox');
            const privacyShield = document.getElementById('seerPrivacyShield');
            // Rebuild the actual target grid on every role turn. Keep it prepared
            // behind the privacy shield, but never leave it hidden from the active role.
            grid.classList.remove('hidden');
            grid.style.display = '';
            if (gameState.mode !== 'pass' || !privacyShield.classList.contains('flex')) {
                interactiveBox.classList.remove('hidden');
                interactiveBox.style.display = '';
            }
            grid.innerHTML = '';

            const alivePlayers = gameState.players.filter(p => p.isAlive);

            let currentHealer = null;
            if (gameState.nightStep === 'healer') {
                currentHealer = alivePlayers.find(p => p.role === 'HEALER');
            }

            const isSeerPhase = gameState.nightStep === 'seer';

            alivePlayers.forEach(p => {
                let isDisabled = false;

                // Wolves cannot target fellow Wolves or themselves
                if (gameState.nightStep === 'wolves') {
                    if (p.role === 'WOLF') {
                        isDisabled = true;
                    }
                }

                if (gameState.nightStep === 'healer' && currentHealer) {
                    if (doctorRule === 'no_self' && p.id === currentHealer.id) isDisabled = true;
                    if (doctorRule === 'no_consecutive' && p.id === currentHealer.lastProtectedId) isDisabled = true;
                    if ((doctorRule === 'max_1' && currentHealer.successfulHeals >= 1) ||
                        (doctorRule === 'max_2' && currentHealer.successfulHeals >= 2)) isDisabled = true;
                }

                // Prevent Seer and Hunter from selecting self + check capacity rules
                if (isSeerPhase) {
                    const seerPlayer = gameState.players.find(sp => sp.role === 'SEER' && sp.isAlive);
                    if (seerPlayer) {
                        if (p.id === seerPlayer.id) isDisabled = true;
                        // A Seer may inspect only one player per night.
                        if (gameState.nightTargets.seerInspect !== null) isDisabled = true;
                        if (seerRule !== 'unlimited') {
                            const maxAllowed = parseInt(seerRule.split('_')[1]);
                            if (seerPlayer.seerInspectionsCount >= maxAllowed) isDisabled = true;
                        }
                    }
                } else if (gameState.nightStep === 'hunter') {
                    const hunterPlayer = gameState.players.find(hp => hp.role === 'HUNTER' && hp.isAlive);
                    if (hunterPlayer) {
                        if (p.id === hunterPlayer.id) isDisabled = true;
                        if (hunterRule !== 'unlimited') {
                            const maxAllowed = parseInt(hunterRule.split('_')[1]);
                            if (hunterPlayer.hunterShotsFired >= maxAllowed) isDisabled = true;
                        }
                    }
                }

                const card = document.createElement('div');
                let isSelected = gameState.selectedNightTarget === p.id;

                card.className = `wolf-btn p-3.5 text-center flex flex-col items-center justify-center space-y-2 rounded-xl transition ${isDisabled ? 'opacity-30 grayscale cursor-not-allowed' : ''} ${isSelected ? 'border-amber-400 bg-amber-500/20 shadow-lg ring-2 ring-amber-400' : ''}`;
                if (isSelected) {
                    card.style.border = '2px solid #fbbf24';
                    card.style.background = 'rgba(245, 158, 11, 0.28)';
                    card.style.boxShadow = '0 0 0 3px rgba(251, 191, 36, 0.25)';
                }

                if (isSeerPhase) {
                    card.innerHTML = `
                        <div class="w-10 h-10 rounded-full bg-slate-800 border border-slate-700 flex items-center justify-center text-sm font-bold text-slate-300">
                            ${p.name.substring(0, 2).toUpperCase()}
                        </div>
                        <span class="text-xs font-bold text-white truncate max-w-full">${p.name}</span>
                        <button onclick="inspectTargetAsSeer(${p.id})" ${isDisabled ? 'disabled' : ''} class="wolf-btn wolf-btn-primary px-3 py-1.5 text-[10px] font-bold uppercase tracking-wider w-full">
                            <i class="fas fa-eye mr-1"></i> Inspect Role
                        </button>
                    `;
                } else {
                    card.onclick = () => { if (!isDisabled) selectNightTarget(p.id); };
                    card.innerHTML = `
                        <div class="w-10 h-10 rounded-full bg-slate-800 border border-slate-700 flex items-center justify-center text-sm font-bold text-slate-300">
                            ${p.name.substring(0, 2).toUpperCase()}
                        </div>
                        <span class="text-xs font-bold text-white truncate max-w-full">${p.name}</span>
                        ${isSelected ? '<span class="text-[10px] font-extrabold uppercase tracking-wider text-amber-300"><i class="fas fa-check-circle mr-1"></i>Selected</span>' : ''}
                        ${isDisabled ? `<span class="text-[9px] ${p.role === 'WOLF' ? 'text-red-400' : 'text-amber-400'} uppercase font-bold">${p.role === 'WOLF' ? 'Teammate / Self' : 'Restricted'}</span>` : ''}
                    `;
                }

                grid.appendChild(card);
            });
        }

        // Select a target during non-Seer night turns (Wolves, Healer, or Hunter).
        // This handler was missing, so the player cards looked clickable but did nothing.
        function selectNightTarget(targetId) {
            const target = gameState.players.find(p => p.id === targetId && p.isAlive);
            if (!target) return;

            // Enforce each role's restrictions again when a target is clicked.
            if (gameState.nightStep === 'wolves' && target.role === 'WOLF') return;

            if (gameState.nightStep === 'healer') {
                const healer = gameState.players.find(p => p.role === 'HEALER' && p.isAlive);
                if (healer) {
                    if (doctorRule === 'no_self' && target.id === healer.id) return;
                    if (doctorRule === 'no_consecutive' && target.id === healer.lastProtectedId) return;
                    if ((doctorRule === 'max_1' && healer.successfulHeals >= 1) ||
                        (doctorRule === 'max_2' && healer.successfulHeals >= 2)) return;
                }
            }

            if (gameState.nightStep === 'hunter') {
                const hunter = gameState.players.find(p => p.role === 'HUNTER' && p.isAlive);
                if (hunter) {
                    if (target.id === hunter.id) return;
                    if (hunterRule !== 'unlimited') {
                        const maxAllowed = parseInt(hunterRule.split('_')[1], 10);
                        if (hunter.hunterShotsFired >= maxAllowed) return;
                    }
                }
            }

            gameState.selectedNightTarget = targetId;
            playSound('select');
            renderNightPlayerGrid();
            animateTargetSelection('nightPlayerGrid');
        }

        function inspectTargetAsSeer(targetId) {
            // Block repeat inspections during the same night, even if called directly.
            if (gameState.nightTargets.seerInspect !== null) return;
            playSound('inspect');
            flashFX('blue');
            const targetPlayer = gameState.players.find(p => p.id === targetId);
            const seerPlayer = gameState.players.find(p => p.role === 'SEER' && p.isAlive);
            if (!targetPlayer) return;

            if (seerPlayer) seerPlayer.seerInspectionsCount++;

            document.getElementById('seerTargetName').textContent = targetPlayer.name;
            const resultBadge = document.getElementById('seerResultBadge');

            const isWolf = targetPlayer.role === 'WOLF';
            resultBadge.textContent = isWolf ? 'WOLF / THREAT' : 'INNOCENT';
            resultBadge.className = isWolf
                ? "p-4 rounded-xl font-serif text-lg font-bold uppercase tracking-wider bg-red-950/80 border border-red-500 text-red-400"
                : "p-4 rounded-xl font-serif text-lg font-bold uppercase tracking-wider bg-emerald-950/80 border border-emerald-500 text-emerald-400";

            gameState.nightTargets.seerInspect = targetId;
            renderNightPlayerGrid();
            openModal('seerModal');

            if (gameState.mode === 'pass') {
                document.getElementById('hideSeerTurnBtn').classList.remove('hidden');
                document.getElementById('confirmNightActionBtn').classList.add('hidden');
            }
        }

        // Reveal the current role's private night-action screen after the device is passed safely.
        function revealNightRoleScreen() {
            playSound('click');
            const shield = document.getElementById('seerPrivacyShield');
            const nightBox = document.getElementById('nightInteractiveBox');
            const nightGrid = document.getElementById('nightPlayerGrid');
            // Restore the correct handler in case the shared button was used for voting.
            const revealButton = document.getElementById('revealNightRoleBtn');
            if (revealButton) revealButton.onclick = revealNightRoleScreen;
            shield.classList.add('hidden');
            shield.classList.remove('flex');
            nightBox.classList.remove('hidden');
            nightBox.style.display = '';
            if (nightGrid) {
                nightGrid.classList.remove('hidden');
                nightGrid.style.display = '';
            }
            // Re-render after opening so Night 2+ always has fresh, visible choices.
            renderNightPlayerGrid();
        }

        // Backwards-compatible name for any older markup calling this handler.
        function revealSeerNightScreen() {
            revealNightRoleScreen();
        }

        // Hide the Seer's result before passing the device back and continue the night sequence.
        function hideAndCompleteSeerTurn() {
            closeModal('seerModal');
            document.getElementById('seerPrivacyShield').classList.remove('hidden');
            document.getElementById('seerPrivacyShield').classList.add('flex');
            document.getElementById('nightInteractiveBox').classList.add('hidden');
            document.getElementById('hideSeerTurnBtn').classList.add('hidden');
            document.getElementById('confirmNightActionBtn').classList.remove('hidden');
            advanceNightStep();
        }

        function submitNightStep() {
            playSound('click');
            if (gameState.selectedNightTarget) {
                if (gameState.nightStep === 'wolves') {
                    gameState.nightTargets.wolfKill = gameState.selectedNightTarget;
                } else if (gameState.nightStep === 'healer') {
                    gameState.nightTargets.healerProtect = gameState.selectedNightTarget;
                    const healer = gameState.players.find(p => p.role === 'HEALER' && p.isAlive);
                    if (healer) healer.lastProtectedId = gameState.selectedNightTarget;
                } else if (gameState.nightStep === 'hunter') {
                    gameState.nightTargets.hunterTarget = gameState.selectedNightTarget;
                    const hunter = gameState.players.find(p => p.role === 'HUNTER' && p.isAlive);
                    if (hunter) hunter.hunterShotsFired++;
                }
            }

            advanceNightStep();
        }

        function advanceNightStep() {
            const hasHealer = gameState.players.some(p => p.role === 'HEALER' && p.isAlive);
            const hasSeer = gameState.players.some(p => p.role === 'SEER' && p.isAlive);
            const hasHunter = gameState.players.some(p => p.role === 'HUNTER' && p.isAlive);

            if (gameState.nightStep === 'wolves') {
                if (hasHealer) {
                    gameState.nightStep = 'healer';
                    setupNightStepUI();
                } else if (hasSeer) {
                    gameState.nightStep = 'seer';
                    setupNightStepUI();
                } else if (hasHunter) {
                    gameState.nightStep = 'hunter';
                    setupNightStepUI();
                } else {
                    processNightResults();
                }
            } else if (gameState.nightStep === 'healer') {
                if (hasSeer) {
                    gameState.nightStep = 'seer';
                    setupNightStepUI();
                } else if (hasHunter) {
                    gameState.nightStep = 'hunter';
                    setupNightStepUI();
                } else {
                    processNightResults();
                }
            } else if (gameState.nightStep === 'seer') {
                if (hasHunter) {
                    gameState.nightStep = 'hunter';
                    setupNightStepUI();
                } else {
                    processNightResults();
                }
            } else if (gameState.nightStep === 'hunter') {
                processNightResults();
            }
        }

        function processNightResults() {
            let victimId = gameState.nightTargets.wolfKill;
            let protectedId = gameState.nightTargets.healerProtect;
            let hunterShotId = gameState.nightTargets.hunterTarget;

            let perishedPlayer = null;

            // Handle Wolf Attack vs Doctor Protection
            if (victimId && victimId === protectedId) {
                const healer = gameState.players.find(p => p.role === 'HEALER' && p.isAlive);
                const savedPlayer = gameState.players.find(p => p.id === victimId);
                if (healer) healer.successfulHeals++;
                if (savedPlayer) {
                    gameState.nightEvents.push(`HEALER SAVE: ${savedPlayer.name} was attacked by the Wolves, but the Healer protected them. No one was lost to that attack.`);
                }
            } else if (victimId && victimId !== protectedId) {
                perishedPlayer = gameState.players.find(p => p.id === victimId);
                if (perishedPlayer) perishedPlayer.isAlive = false;
            }

            // Handle Hunter's Night Action: Kills ONLY if target is a Wolf
            if (hunterShotId) {
                const hunterTargetPlayer = gameState.players.find(p => p.id === hunterShotId);
                if (hunterTargetPlayer && hunterTargetPlayer.isAlive) {
                    if (hunterTargetPlayer.role === 'WOLF') {
                        hunterTargetPlayer.isAlive = false;
                        gameState.nightEvents.push(`HUNTER SUCCESS: The Hunter took out ${hunterTargetPlayer.name}, who was a Wolf (Mafia)!`);
                        addChatMessage("System", `Hunter's silver bullet found its target! Wolf ${hunterTargetPlayer.name} was eliminated during the night!`, "text-amber-400 font-bold");
                    } else {
                        addChatMessage("System", `Hunter's shot missed—the target ${hunterTargetPlayer.name} was innocent and survived.`, "text-slate-400 font-semibold");
                    }
                }
            }

            // Check if perished player was Hunter (last stand revenge shot)
            if (perishedPlayer && perishedPlayer.role === 'HUNTER') {
                triggerHunterRevenge(perishedPlayer, () => startDayPhase(perishedPlayer));
            } else {
                startDayPhase(perishedPlayer);
            }
        }


        /* ================= HUNTER REVENGE LOGIC ================= */
        function triggerHunterRevenge(hunterPlayer, callbackOnComplete) {
            gameState.pendingHunterShot = hunterPlayer;
            gameState.selectedHunterShotId = null;

            const aliveTargets = gameState.players.filter(p => p.isAlive && p.id !== hunterPlayer.id);

            if (aliveTargets.length === 0) {
                if (callbackOnComplete) callbackOnComplete();
                return;
            }

            if (hunterPlayer.isAI) {
                // AI Hunter shoots random alive player
                const target = aliveTargets[Math.floor(Math.random() * aliveTargets.length)];
                if (target.role === 'WOLF') {
                    target.isAlive = false;
                    addChatMessage("Hunter " + hunterPlayer.name, `Fired a dying shot and successfully eliminated Wolf ${target.name}!`, "text-amber-400 font-bold");
                } else {
                    addChatMessage("Hunter " + hunterPlayer.name, `Fired a dying shot at ${target.name}, but the bullet passed through harmlessly—${target.name} is innocent!`, "text-slate-400 font-semibold");
                }
                if (callbackOnComplete) callbackOnComplete();
            } else {
                // Human Hunter Modal Target Picker
                const grid = document.getElementById('hunterTargetGrid');
                grid.innerHTML = '';

                aliveTargets.forEach(t => {
                    const card = document.createElement('button');
                    card.onclick = () => {
                        playSound('click');
                        gameState.selectedHunterShotId = t.id;
                        document.getElementById('confirmHunterShootBtn').disabled = false;

                        Array.from(grid.children).forEach(c => c.className = "wolf-btn p-3 text-center rounded-xl");
                        card.className = "wolf-btn p-3 text-center rounded-xl border-amber-400 bg-amber-500/20";
                    };
                    card.className = "wolf-btn p-3 text-center rounded-xl";
                    card.innerHTML = `<span class="text-xs font-bold text-white">${t.name}</span>`;
                    grid.appendChild(card);
                });

                gameState.hunterShotCallback = callbackOnComplete;
                openModal('hunterModal');
            }
        }

        function confirmHunterShot() {
            playSound('shot');
            flashFX('red');
            if (gameState.selectedHunterShotId) {
                const target = gameState.players.find(p => p.id === gameState.selectedHunterShotId);
                if (target) {
                    if (target.role === 'WOLF') {
                        target.isAlive = false;
                        addChatMessage("Hunter " + gameState.pendingHunterShot.name, `Fired a dying silver bullet and eliminated Wolf ${target.name}!`, "text-amber-400 font-bold");
                    } else {
                        addChatMessage("Hunter " + gameState.pendingHunterShot.name, `Fired a dying shot at ${target.name}, but it missed—${target.name} is innocent and unharmed!`, "text-slate-400 font-semibold");
                    }
                }
            }
            closeModal('hunterModal');
            if (gameState.hunterShotCallback) gameState.hunterShotCallback();
        }


        /* ================= DAY PHASE & DISCUSSION ================= */
        function startDayPhase(perishedPlayer) {
            gameState.phase = 'day';
            // Clear the previous night's privacy screen before daytime discussion.
            // Fresh private voting overlays are shown later by promptPassVote().
            const transitionShield = document.getElementById('seerPrivacyShield');
            transitionShield.classList.add('hidden');
            transitionShield.classList.remove('flex');
            document.body.classList.add('day-phase');
            setMusicPhase('day');
            playSound('dawn');
            cueCinematic('DAY '+gameState.currentDay, 'DAWN BREAKS','day-scene','fa-sun');

            announceRoleCall("Everyone wake up. Morning has broken.");

            const newsEl = document.getElementById('morningNewsText');
            const morningMessages = [];
            if (perishedPlayer) {
                morningMessages.push(`Regrettably, <span class="font-bold text-red-400">${perishedPlayer.name}</span> (${ROLES[perishedPlayer.role].title}) was found perished during the night.`);
            } else {
                morningMessages.push(`Miraculously, <span class="font-bold text-emerald-400">no one was killed by the Wolves</span> during the night.`);
            }
            (gameState.nightEvents || []).forEach(eventText => {
                let safeEvent = eventText.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
                if (safeEvent.startsWith('HEALER SAVE:')) {
                    const healerAnnouncement = healerSaveDisclosure === 'secret'
                        ? 'HEALER SAVE: The Healer protected the player targeted by the Wolves. The protected player’s identity remains secret.'
                        : safeEvent;
                    morningMessages.push(`<span class="font-bold text-emerald-400">${healerAnnouncement}</span>`);
                } else if (safeEvent.startsWith('HUNTER SUCCESS:')) {
                    morningMessages.push(`<span class="font-bold text-amber-400">${safeEvent}</span>`);
                } else {
                    morningMessages.push(safeEvent);
                }
            });
            newsEl.innerHTML = morningMessages.join('<br><br>');

            gameState.votes = {};
            gameState.selectedVoteId = null;
            gameState.passVoteOrder = null;
            gameState.passVoteIndex = 0;
            document.getElementById('submitVoteBtn').disabled = true;

            const chatLog = document.getElementById('chatLog');
            chatLog.innerHTML = `<div class="text-slate-400 italic text-center text-[11px] py-1 border-b border-slate-800">Night ${gameState.currentDay} Summary: ${perishedPlayer ? perishedPlayer.name + ' perished.' : 'No deaths.'}</div>`;

            if (gameState.mode === 'solo' && gameState.players[0].isAlive) {
                document.getElementById('chatInputArea').classList.remove('hidden');
            } else {
                document.getElementById('chatInputArea').classList.add('hidden');
            }

            switchView('viewDay');
            renderDayPlayerGrid();

            if (checkWinConditions()) return;

            startDiscussionTimer();

            if (gameState.mode === 'solo') {
                generateBotChatter();
            }
        }

        function startDiscussionTimer() {
            clearInterval(gameState.discussionTimer);
            gameState.timerSeconds = 90;
            updateTimerDisplay();

            gameState.discussionTimer = setInterval(() => {
                gameState.timerSeconds--;
                updateTimerDisplay();
                if(gameState.timerSeconds > 0 && gameState.timerSeconds <= 5)playSound('tick');
                if (gameState.timerSeconds <= 0) {
                    clearInterval(gameState.discussionTimer);
                    document.getElementById('voteStatusBadge').textContent = "Voting Active";
                    document.getElementById('voteStatusBadge').className = "text-[10px] bg-red-500/20 text-red-400 px-2.5 py-1 rounded-full font-bold";
                    if (gameState.mode === 'pass') startPassVoting();
                }
            }, 1000);
        }

        function updateTimerDisplay() {
            const mins = Math.floor(gameState.timerSeconds / 60).toString().padStart(2, '0');
            const secs = (gameState.timerSeconds % 60).toString().padStart(2, '0');
            const t=document.getElementById('timerDisplay');
            t.textContent = `${mins}:${secs}`;
            t.classList.toggle('timer-urgent', gameState.timerSeconds<=10);
        }

        function skipDiscussionTimer() {
            playSound('click');
            gameState.timerSeconds = 0;
            updateTimerDisplay();
            clearInterval(gameState.discussionTimer);
            document.getElementById('voteStatusBadge').textContent = "Voting Active";
            document.getElementById('voteStatusBadge').className = "text-[10px] bg-red-500/20 text-red-400 px-2.5 py-1 rounded-full font-bold";
            if (gameState.mode === 'pass') startPassVoting();
        }

        function renderDayPlayerGrid() {
            const grid = document.getElementById('dayPlayerGrid');
            grid.innerHTML = '';
            const currentPassVoterId = gameState.mode === 'pass' && Array.isArray(gameState.passVoteOrder)
                ? gameState.passVoteOrder[gameState.passVoteIndex]
                : null;

            gameState.players.forEach(p => {
                const card = document.createElement('button');
                const isCurrentVoter = currentPassVoterId !== null && p.id === currentPassVoterId;
                if (p.isAlive && !isCurrentVoter) {
                    card.onclick = () => selectDayVote(p.id);
                } else {
                    card.disabled = true;
                }

                let isSelected = gameState.selectedVoteId === p.id;
                card.className = `wolf-btn p-3 text-center flex flex-col items-center justify-center space-y-1.5 rounded-xl transition ${(!p.isAlive || isCurrentVoter) ? 'opacity-40 grayscale cursor-not-allowed' : ''} ${isSelected ? 'border-red-400 bg-red-500/20 shadow-lg ring-2 ring-red-400' : ''}`;
                if (isSelected) {
                    card.style.border = '2px solid #f87171';
                    card.style.background = 'rgba(239, 68, 68, 0.28)';
                    card.style.boxShadow = '0 0 0 3px rgba(248, 113, 113, 0.25)';
                }

                card.innerHTML = `
                    <div class="w-9 h-9 rounded-full bg-slate-800 border border-slate-700 flex items-center justify-center text-xs font-bold text-slate-300">
                        ${p.name.substring(0, 2).toUpperCase()}
                    </div>
                    <span class="text-xs font-bold text-white truncate max-w-full">${p.name}</span>
                    <span class="text-[10px] ${p.isAlive ? 'text-emerald-400' : 'text-red-400'} font-bold">${!p.isAlive ? 'Eliminated' : (isCurrentVoter ? 'Your turn to vote' : (isSelected ? '✓ SELECTED' : 'Alive'))}</span>
                `;
                grid.appendChild(card);
            });
            syncMobileVoteDock();
        }

        function selectDayVote(targetId) {
            playSound('click');
            const currentPassVoterId = gameState.mode === 'pass' && Array.isArray(gameState.passVoteOrder)
                ? gameState.passVoteOrder[gameState.passVoteIndex]
                : null;
            if (currentPassVoterId === targetId) return; // Players cannot vote for themselves.
            const target = gameState.players.find(p => p.id === targetId);
            if (!target || !target.isAlive) return;
            gameState.selectedVoteId = targetId;
            document.getElementById('submitVoteBtn').disabled = false;
            renderDayPlayerGrid();
            animateTargetSelection('dayPlayerGrid');
        }

        function startPassVoting() {
            if (gameState.mode !== 'pass' || Array.isArray(gameState.passVoteOrder)) return;
            gameState.votes = {};
            gameState.passVoteOrder = gameState.players.filter(p => p.isAlive).map(p => p.id);
            gameState.passVoteIndex = 0;
            promptPassVote();
        }

        function promptPassVote() {
            const alivePlayers = gameState.players.filter(p => p.isAlive);
            // Remove anyone eliminated before their turn (for example, by a special effect).
            gameState.passVoteOrder = gameState.passVoteOrder.filter(id => alivePlayers.some(p => p.id === id));
            if (gameState.passVoteIndex >= gameState.passVoteOrder.length) {
                gameState.passVoteOrder = null;
                resolveDayVote();
                return;
            }
            const voter = gameState.players.find(p => p.id === gameState.passVoteOrder[gameState.passVoteIndex]);
            if (!voter) return;
            gameState.selectedVoteId = null;
            document.getElementById('submitVoteBtn').disabled = true;
            document.getElementById('seerPrivacyName').textContent = `Pass Device To ${voter.name}`;
            document.getElementById('privacyShieldInstructions').textContent = `It is ${voter.name}'s turn to vote. Keep your choice secret; tap below only when you are ready to vote.`;
            const revealBtn = document.getElementById('revealNightRoleBtn');
            revealBtn.innerHTML = '<i class="fas fa-vote-yea mr-2"></i> I Am Ready To Vote';
            revealBtn.onclick = revealPassVoteScreen;
            const shield = document.getElementById('seerPrivacyShield');
            shield.classList.remove('hidden');
            shield.classList.add('flex');
            document.getElementById('voteStatusBadge').textContent = `Vote ${gameState.passVoteIndex + 1} of ${gameState.passVoteOrder.length}`;
            renderDayPlayerGrid();
        }

        function revealPassVoteScreen() {
            const shield = document.getElementById('seerPrivacyShield');
            shield.classList.add('hidden');
            shield.classList.remove('flex');
            const voter = gameState.players.find(p => Array.isArray(gameState.passVoteOrder) && p.id === gameState.passVoteOrder[gameState.passVoteIndex]);
            document.getElementById('votingSectionTitle').textContent = voter ? `${voter.name.toUpperCase()} — CAST YOUR VOTE` : 'Cast Your Banishment Vote';
            document.getElementById('revealNightRoleBtn').onclick = revealNightRoleScreen;
            renderDayPlayerGrid();
        }

        function sendHumanChatMessage() {
            const input = document.getElementById('humanChatMessage');
            const text = input.value.trim();
            if (!text) return;

            addChatMessage(gameState.players[0].name, text, 'text-blue-400');
            input.value = '';
        }

        function addChatMessage(author, text, colorClass = 'text-amber-400') {
            const log = document.getElementById('chatLog');
            const msg = document.createElement('div');
            msg.className = "p-2 rounded-lg bg-slate-900/80 border border-slate-800 space-y-0.5";
            msg.innerHTML = `<span class="font-bold text-[11px] ${colorClass}">${author}:</span> <span class="text-slate-200">${text}</span>`;
            log.appendChild(msg);
            log.scrollTop = log.scrollHeight;
        }

        function generateBotChatter() {
            const aliveBots = gameState.players.filter(p => p.isAlive && p.isAI);
            const accusations = [
                "I saw them whispering in the fog last night...",
                "They were suspiciously quiet during the morning announcement.",
                "I trust them for now. Let's focus on finding the real wolf.",
                "Why are you pushing so hard on me? Sounds like a wolf move!",
                "Look at the voting patterns. It's obvious!"
            ];

            aliveBots.forEach((bot, index) => {
                setTimeout(() => {
                    if (gameState.phase !== 'day') return;
                    const text = accusations[Math.floor(Math.random() * accusations.length)];
                    addChatMessage(bot.name, text);
                }, (index + 1) * 3500);
            });
        }

        function submitDayVote() {
            playSound('vote');
            flashFX('red');

            // Pass & Play: every living human player casts one private vote in sequence.
            if (gameState.mode === 'pass') {
                if (!Array.isArray(gameState.passVoteOrder)) {
                    gameState.votes = {};
                    gameState.passVoteOrder = gameState.players.filter(p => p.isAlive).map(p => p.id);
                    gameState.passVoteIndex = 0;
                    promptPassVote();
                    return;
                }
                const voterId = gameState.passVoteOrder[gameState.passVoteIndex];
                const target = gameState.players.find(p => p.id === gameState.selectedVoteId && p.isAlive && p.id !== voterId);
                if (!target) {
                    const status = document.getElementById('voteStatusBadge');
                    if (status) status.textContent = 'Choose another living player first';
                    return;
                }
                gameState.votes[voterId] = target.id;
                gameState.passVoteIndex++;
                if (gameState.passVoteIndex < gameState.passVoteOrder.length) {
                    promptPassVote();
                } else {
                    gameState.passVoteOrder = null;
                    document.getElementById('seerPrivacyShield').classList.add('hidden');
                    document.getElementById('seerPrivacyShield').classList.remove('flex');
                    document.getElementById('votingSectionTitle').textContent = 'Cast Your Banishment Vote';
                    resolveDayVote();
                }
                return;
            }

            resolveDayVote();
        }

        function resolveDayVote() {
            const alivePlayers = gameState.players.filter(p => p.isAlive);
            const humanPlayer = alivePlayers.find(p => p.id === gameState.players[0]?.id);

            // Require the human player to choose a living player before the verdict is submitted.
            if (humanPlayer && !alivePlayers.some(p => p.id === gameState.selectedVoteId)) {
                const status = document.getElementById('voteStatusBadge');
                if (status) status.textContent = 'Choose a living player first';
                return;
            }

            // Solo mode: bots vote automatically and the human player chooses one target.
            // Pass & Play votes were already collected privately, one player at a time.
            if (gameState.mode !== 'pass') {
                gameState.votes = {};
                alivePlayers.forEach(p => {
                    if (p.isAI) {
                        const targets = alivePlayers.filter(target => target.id !== p.id);
                        if (targets.length > 0) {
                            const chosen = targets[Math.floor(Math.random() * targets.length)];
                            gameState.votes[p.id] = chosen.id;
                        }
                    } else if (humanPlayer && p.id === humanPlayer.id) {
                        gameState.votes[p.id] = gameState.selectedVoteId;
                    }
                });
            }

            const aliveIds = new Set(alivePlayers.map(p => p.id));
            const tally = {};
            Object.entries(gameState.votes).forEach(([voterId, targetId]) => {
                const voter = gameState.players.find(p => p.id === Number(voterId));
                // Only living players may vote, and votes only count for living targets.
                if (voter && voter.isAlive && aliveIds.has(targetId)) {
                    tally[targetId] = (tally[targetId] || 0) + 1;
                }
            });

            let maxVotes = 0;
            let eliminatedId = null;
            let isTie = false;

            Object.entries(tally).forEach(([targetId, count]) => {
                if (count > maxVotes) {
                    maxVotes = count;
                    eliminatedId = Number(targetId);
                    isTie = false;
                } else if (count === maxVotes) {
                    isTie = true;
                }
            });

            const elimModalDesc = document.getElementById('eliminationDesc');
            const elimRoleName = document.getElementById('eliminatedRoleName');

            if (!isTie && eliminatedId !== null) {
                const eliminatedPlayer = gameState.players.find(p => p.id === eliminatedId && p.isAlive);

                if (eliminatedPlayer) {
                    // The verdict eliminates the player with the most votes, even when they are innocent.
                    eliminatedPlayer.isAlive = false;
                    gameState.lastEliminatedPlayer = eliminatedPlayer;

                    if (eliminatedPlayer.role === 'WOLF') {
                        elimModalDesc.innerHTML = `The pack voted with a majority (${maxVotes} votes). <br><span class="font-bold text-emerald-400">JUSTICE SERVED!</span> ${eliminatedPlayer.name} was eliminated and revealed to be a Wolf!`;
                    } else {
                        elimModalDesc.innerHTML = `The verdict was WRONG! <br><span class="font-bold text-red-400">${eliminatedPlayer.name} was innocent, but is still ELIMINATED.</span> The town made a fatal mistake.`;
                    }

                    elimRoleName.textContent = ROLES[eliminatedPlayer.role]?.title || eliminatedPlayer.role;
                } else {
                    gameState.lastEliminatedPlayer = null;
                    elimModalDesc.textContent = 'No valid living player received the verdict. No one was eliminated.';
                    elimRoleName.textContent = 'NO ONE ELIMINATED';
                }
            } else {
                gameState.lastEliminatedPlayer = null;
                elimModalDesc.textContent = 'The vote ended in a tie! No one was eliminated.';
                elimRoleName.textContent = 'NO ONE ELIMINATED';
            }

            flashFX(gameState.lastEliminatedPlayer && gameState.lastEliminatedPlayer.role==='WOLF' ? 'green' : 'red');
            playSound(gameState.lastEliminatedPlayer && gameState.lastEliminatedPlayer.role==='WOLF' ? 'heal' : 'danger');
            openModal('eliminationModal');
        }

        function handlePostElimination() {
            const elimPlayer = gameState.lastEliminatedPlayer;

            // Check win conditions immediately following elimination
            if (checkWinConditions()) return;

            // Trigger Hunter revenge if the banished innocent/wolf was the Hunter
            if (elimPlayer && elimPlayer.role === 'HUNTER') {
                triggerHunterRevenge(elimPlayer, () => proceedToNight());
            } else {
                proceedToNight();
            }
        }

        function proceedToNight() {
            if (checkWinConditions()) return;

            gameState.currentDay++;
            startNightPhase();
        }


        /* ================= WIN CONDITIONS & END SCREEN ================= */
        function checkWinConditions() {
            const alivePlayers = gameState.players.filter(p => p.isAlive);
            const aliveWolves = alivePlayers.filter(p => p.role === 'WOLF');
            const aliveVillagers = alivePlayers.filter(p => p.role !== 'WOLF');

            if (aliveWolves.length === 0) {
                showGameOver('TOWN VICTORY', 'THE VILLAGERS SURVIVED', 'All wolves have been banished from the pack.');
                return true;
            } else if (aliveWolves.length >= aliveVillagers.length) {
                showGameOver('WOLF VICTORY', 'THE WOLVES OVERTOOK THE PACK', 'The wolves now control the wilderness.');
                return true;
            }
            return false;
        }

        function showGameOver(tag, title, sub) {
            const wolfWin=tag.startsWith('WOLF');
            clearInterval(gameState.discussionTimer);
            setMusicPhase(wolfWin?'defeat':'victory');
            playSound(wolfWin?'defeat':'victory');
            cueCinematic(wolfWin?'THE PACK FALLS':'THE PACK SURVIVES', wolfWin?'WOLVES VICTORIOUS':'VILLAGE VICTORY',wolfWin?'danger-scene':'victory-scene',wolfWin?'fa-paw':'fa-trophy');
            flashFX(wolfWin?'red':'gold');
            switchView('viewGameOver');
            sparkVictory(wolfWin);

            document.getElementById('winnerTeamTag').textContent = tag;
            document.getElementById('winnerTitle').textContent = title;
            document.getElementById('winnerSub').textContent = sub;

            const recapList = document.getElementById('recapRoleList');
            recapList.innerHTML = '';

            gameState.players.forEach(p => {
                const item = document.createElement('div');
                item.className = "p-3 rounded-xl bg-slate-900 border border-slate-800 flex items-center justify-between text-xs";
                const roleObj = ROLES[p.role];

                item.innerHTML = `
                    <div class="flex items-center space-x-3">
                        <i class="fas ${roleObj.icon} ${roleObj.color}"></i>
                        <span class="font-bold text-white">${p.name}</span>
                    </div>
                    <div class="flex items-center space-x-2">
                        <span class="${roleObj.color} font-bold">${roleObj.title}</span>
                        <span class="text-[10px] text-slate-500">(${p.isAlive ? 'Survived' : 'Fell'})</span>
                    </div>
                `;
                recapList.appendChild(item);
            });
        }



        // Mobile ballot mirrors the original button without altering voting decisions.
        function syncMobileVoteDock() {
            const mobileButton = document.getElementById('mobileSubmitVoteBtn');
            const desktopButton = document.getElementById('submitVoteBtn');
            const hint = document.getElementById('mobileVoteHint');
            if (!mobileButton || !desktopButton || !hint) return;
            const player = gameState.players.find(p => p.isAlive && p.id === gameState.selectedVoteId);
            const shield = document.getElementById('seerPrivacyShield');
            const shieldVisible = shield && !shield.classList.contains('hidden');
            const isVoting = gameState.phase === 'day' && !document.getElementById('viewDay').classList.contains('hidden');
            mobileButton.disabled = !isVoting || !!shieldVisible || desktopButton.disabled || !player;
            hint.textContent = shieldVisible && isVoting
                ? 'Pass the device privately before voting'
                : player ? `Selected: ${player.name}` : 'Select a player above to cast a vote';
            mobileButton.setAttribute('aria-label', player ? `Cast vote for ${player.name}` : 'Cast vote after choosing a player');
        }

        /* ================= UI UTILITIES ================= */
        function switchView(viewId) {
            ['viewSetup', 'viewRoleReveal', 'viewNight', 'viewDay', 'viewGameOver'].forEach(id => {
                const el = document.getElementById(id);
                if (el) el.classList.add('hidden');
            });
            const target = document.getElementById(viewId);
            if (target) target.classList.remove('hidden');
            document.body.classList.toggle('wolves-day-view', viewId === 'viewDay');
            syncMobileVoteDock();
            // New screen starts at the top; avoid inheriting the long setup page scroll.
            window.scrollTo(0, 0);
        }

        function openModal(id) {
            const modal = document.getElementById(id);
            if (modal) modal.classList.add('active');
            if(id==='hunterModal'){playSound('danger');flashFX('red');}
        }

        function closeModal(id) {
            const modal = document.getElementById(id);
            if (modal) modal.classList.remove('active');
        }

        function returnToMainMenu() {
            playSound('click');
            clearInterval(gameState.discussionTimer);
            document.body.classList.remove('day-phase');
            const privacyCover = document.getElementById('seerPrivacyShield');
            privacyCover.classList.add('hidden');
            privacyCover.classList.remove('flex');
            setMusicPhase('menu');
            switchView('viewSetup');
        }


        /* ================= BACKGROUND CANVAS PARTICLES ================= */
        const canvas = document.getElementById('particleCanvas');
        const ctx = canvas.getContext('2d');
        let particles = [];

        function resizeCanvas() {
            canvas.width = window.innerWidth;
            canvas.height = window.innerHeight;
        }
        window.addEventListener('resize', resizeCanvas);
        resizeCanvas();

        class EmberParticle {
            constructor() {
                this.reset();
            }

            reset() {
                this.x = Math.random() * canvas.width;
                this.y = canvas.height + 10;
                this.size = Math.random() * 2.5 + 1;
                this.speedY = -(Math.random() * 0.7 + 0.3);
                this.speedX = Math.random() * 0.5 - 0.25;
                this.opacity = Math.random() * 0.5 + 0.2;
            }

            update() {
                this.y += this.speedY;
                this.x += Math.sin(this.y * 0.01) + this.speedX;
                if (this.y < -10) this.reset();
            }

            draw() {
                ctx.save();
                ctx.beginPath();
                ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
                ctx.fillStyle = document.body.classList.contains('day-phase') ? `rgba(251, 191, 110, ${this.opacity*.65})` : `rgba(147, 197, 253, ${this.opacity})`;
                ctx.shadowBlur = 6;
                ctx.shadowColor = document.body.classList.contains('day-phase') ? 'rgba(251, 191, 110, 0.7)' : 'rgba(147, 197, 253, 0.8)';
                ctx.fill();
                ctx.restore();
            }
        }

        for (let i = 0; i < 40; i++) {
            const p = new EmberParticle();
            p.y = Math.random() * canvas.height;
            particles.push(p);
        }

        function animateParticles() {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            if (!document.hidden && motionAllowed()) {
                particles.forEach(p => {p.update();p.draw();});
            }
            requestAnimationFrame(animateParticles);
        }
        animateParticles();

        // Initialize setup defaults
        updatePlayerCount(7);
        initializeAudioControls();
        bindAnimationFeedback();
    